--
-- Structure de la table `parametres`
--

CREATE TABLE `parametres` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `nom_entreprise` varchar(255) NOT NULL,
  `email_entreprise` varchar(255) DEFAULT NULL,
  `telephone_entreprise` varchar(255) DEFAULT NULL,
  `adresse_entreprise` text DEFAULT NULL,
  `chemin_logo` varchar(255) DEFAULT NULL,
  `chemin_fond_facture` varchar(255) DEFAULT NULL,
  `devise` varchar(10) NOT NULL DEFAULT 'USD',
  `taux_tva_defaut` decimal(5,2) NOT NULL DEFAULT 0.00,
  `pourcentage_remise_defaut` decimal(5,2) NOT NULL DEFAULT 0.00,
  `format_numero_facture` varchar(255) NOT NULL DEFAULT 'FAC-{YEAR}-{SEQ}',
  `delai_echeance_facture_jours` int(11) NOT NULL DEFAULT 15,
  `seuil_stock_minimum_global` int(11) NOT NULL DEFAULT 5,
  `nom_banque` varchar(255) DEFAULT NULL,
  `nom_compte_bancaire` varchar(255) DEFAULT NULL,
  `numero_compte_bancaire` varchar(255) DEFAULT NULL,
  `code_swift` varchar(255) DEFAULT NULL,
  `conditions_facture` text DEFAULT NULL,
  `couleur_principale_facture` varchar(20) NOT NULL DEFAULT '#0f172a',
  `couleur_secondaire_facture` varchar(20) NOT NULL DEFAULT '#e11d48',
  `titre_facture` varchar(255) NOT NULL DEFAULT 'FACTURE',
  `libelle_emetteur_facture` varchar(255) NOT NULL DEFAULT 'Emetteur',
  `libelle_facturer_a` varchar(255) NOT NULL DEFAULT 'Facturer a',
  `libelle_envoyer_a` varchar(255) NOT NULL DEFAULT 'Envoyer a',
  `libelle_paiement_facture` varchar(255) NOT NULL DEFAULT 'Conditions et modalites de paiement',
  `libelle_signature_facture` varchar(255) NOT NULL DEFAULT 'Signature autorisee',
  `libelle_banque_pied_facture` varchar(255) NOT NULL DEFAULT 'Banque',
  `libelle_compte_pied_facture` varchar(255) NOT NULL DEFAULT 'Compte',
  `libelle_contact_pied_facture` varchar(255) NOT NULL DEFAULT 'Contact',
  `libelle_description_facture` varchar(255) NOT NULL DEFAULT 'Description',
  `libelle_quantite_facture` varchar(255) NOT NULL DEFAULT 'Qte',
  `libelle_prix_unitaire_facture` varchar(255) NOT NULL DEFAULT 'Prix unitaire',
  `libelle_montant_facture` varchar(255) NOT NULL DEFAULT 'Montant',
  `afficher_signature_facture` tinyint(1) NOT NULL DEFAULT 1,
  `note_pied_facture` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

